void* writer(void* arg) {
    int writer_id = *(int*)arg;

    while (1) {
        // 模拟写操作间隔
        usleep(200000);  // 0.2秒

        // 获取写锁
        sem_wait(&rw_mutex);

        // 写入共享资源
        shared_data++;
        printf("写者 %d 写入数据: %d\n", writer_id, shared_data);
        usleep(100000);  // 模拟写操作耗时

        // 释放写锁
        sem_post(&rw_mutex);
    }
    return NULL;
}

int main() {
    const int NUM_READERS = 3;
    const int NUM_WRITERS = 2;
    const int RUN_TIME = 5;  // 运行5秒

